1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Both catalogue figures are read through this one row lookup, so an item's type
48	// is resolved against the catalogue in exactly one place.
49	const catalogueEntryFor = (item: Item) => CATALOGUE[item.type];
50	
51	// Totalling a catalogue column over a list of items is the same operation on the
52	// premium side and the claim side; only the column differs. Naming it once keeps
53	// the two columns visibly separate — which is the point: the building-block
54	// discount rewrites the basePremium column and never touches insuranceValue.
55	const totalOfColumn =
56	  (columnOf: (item: Item) => number) =>
57	  (items: Item[]): number =>
58	    items.reduce((total, item) => total + columnOf(item), 0);
59	
60	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
61	
62	const BLOCK_SIZE = 3;
63	const BLOCK_BASE_PREMIUM = 60;
64	
65	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
66	  alikeItems.length === BLOCK_SIZE;
67	
68	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
69	
70	const CURSE_SURCHARGE_RATE = 0.5;
71	const HIGH_ENCHANTMENT_LEVEL = 5;
72	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
73	
74	const isCursed = (item: Item): boolean => item.cursed === true;
75	
76	// An unenchanted item is enchantment 0, so every threshold reads the level the
77	// same way. The MHPCO sets several enchantment thresholds for different rules;
78	// each names its own level and compares through here.
79	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
80	
81	const carriesEnchantmentSurcharge = (item: Item): boolean =>
82	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
83	
84	// A rate table prices one subject: every row whose risk applies contributes its
85	// rate, and the total is their sum. Both the item surcharges and the policy-wide
86	// modifiers are rate tables — they differ only in what they are applied to.
87	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
88	
89	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
90	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
91	
92	// Every item-specific surcharge is a rate on THAT item's base premium, charged
93	// when its risk applies. Adding a new one means adding a row here — nothing else.
94	const ITEM_SURCHARGES: RateTable<Item> = [
95	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
96	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
97	];
98	
99	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
100	
101	const itemSurchargesOn = (items: Item[]): number =>
102	  items.reduce((sum, item) => sum + basePremiumOf(item) * surchargeRateOn(item), 0);
103	
104	// Items of the same type are "alike"; each group is priced together so a
105	// building block can be recognised.
106	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
107	  ...items
108	    .reduce(
109	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
110	      new Map<string, Item[]>(),
111	    )
112	    .values(),
113	];
114	
115	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
116	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
117	
118	const policyBaseOf = (items: Item[]): number =>
119	  alikeItemGroupsIn(items).reduce(
120	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
121	    0,
122	  );
123	
124	// Rounding always favours the MHPCO. Which direction that is follows from which
125	// way the money moves: an amount the office RECEIVES is rounded up, an amount it
126	// PAYS is rounded down. Naming the two directions makes the rule one concept
127	// rather than two opposite-looking halves, and each call site says which kind of
128	// amount it holds — so the reason for the direction is in the code, not a comment.
129	const settledAsReceived = Math.ceil;
130	const settledAsPaid = Math.floor;
131	
132	const LOYALTY_YEARS = 2;
133	const LOYALTY_DISCOUNT_RATE = -0.2;
134	
135	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
136	
137	// Each item in a quote is treated as a first insurance regardless of customer
138	// history, so this surcharge is unconditional.
139	const appliesUnconditionally = (): boolean => true;
140	
141	const isLongStanding = ({ customer }: QuoteContext): boolean =>
142	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
143	
144	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
145	  precedingQuotes > 0;
146	
147	// A quote is priced from the customer plus its place in the scenario's history.
148	type QuoteContext = { customer: Customer; precedingQuotes: number };
149	
150	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
151	// base that already includes the item surcharges. Surcharges carry a positive
152	// rate, discounts a negative one. Adding a new one means adding a row here.
153	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
154	  { appliesTo: appliesUnconditionally, rate: FIRST_INSURANCE_SURCHARGE_RATE },
155	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
156	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
157	];
158	
159	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
160	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
161	
162	const quoteFor = (items: Item[], context: QuoteContext): Result => {
163	  const policyBase = policyBaseOf(items);
164	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
165	  return {
166	    premium: settledAsReceived(
167	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
168	    ),
169	  };
170	};
171	
172	const DEDUCTIBLE_PER_DAMAGE = 100;
173	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
174	
175	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
176	
177	// The insurance sum totals the value column over every insured item — one item,
178	// one row, no grouping. Blocks are a premium concept and cannot reach it.
179	const insuranceSumOf = totalOfColumn(insuranceValueOf);
180	
181	// A policy created by a quote step, tracked by that step's index so later claims
182	// can find it and draw down its cap.
183	type Policy = { items: Item[]; remainingCap: number };
184	
185	const policyFor = (items: Item[]): Policy => ({
186	  items,
187	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
188	});
189	
190	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
191	const HALF_REIMBURSEMENT_RATE = 0.5;
192	const FULL_REIMBURSEMENT_RATE = 1;
193	
194	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
195	// level: this one halves what a claim pays out, that one raises what a policy
196	// costs. They move independently — deliberately not shared.
197	const reimbursesOnlyHalf = (item: Item): boolean =>
198	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
199	
200	// How much of the damage the MHPCO reimburses, before the deductible bites.
201	const reimbursementRateFor = (item: Item): number =>
202	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
203	
204	// A damage names an item type; the policy holds the item it refers to. Which of
205	// several alike items is picked does not matter yet — no test distinguishes them.
206	const damagedItemIn = (policy: Policy, damage: Damage): Item =>
207	  policy.items.find((item) => item.type === damage.itemType)!;
208	
209	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
210	  damage.amount * reimbursementRateFor(damagedItemIn(policy, damage));
211	
212	// The deductible bites once per damage, after the reimbursement rate is applied
213	// — never the other way round, which would pay out more.
214	const payoutForDamage = (damage: Damage, policy: Policy): number =>
215	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
216	
217	// One incident can damage several items; each damage is settled on its own
218	// (and so bears its own deductible), and the incident pays out their sum.
219	const payoutForIncident = (incident: Incident, policy: Policy): number =>
220	  incident.damages.reduce((sum, damage) => sum + payoutForDamage(damage, policy), 0);
221	
222	// A payout is drawn from the policy's cap, leaving less for later claims.
223	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
224	  ...policy,
225	  remainingCap: policy.remainingCap - payout,
226	});
227	
228	// The policy pays no more than the cap it has left, however large the damage.
229	const payoutWithinCapOf = (policy: Policy, desiredPayout: number): number =>
230	  Math.min(desiredPayout, policy.remainingCap);
231	
232	// Settling a claim pays out and draws the cap down by the same amount, so the
233	// result the customer sees is the payout plus the cap that payout left behind.
234	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
235	  const payout = settledAsPaid(
236	    payoutWithinCapOf(policy, payoutForIncident(incident, policy)),
237	  );
238	  const settledPolicy = capDrawnDownBy(policy, payout);
239	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
240	};
241	
242	// What the scenario has accumulated before the current step: the results so far,
243	// the history a quote is priced against, and the policies earlier quotes created.
244	type ScenarioState = {
245	  results: Result[];
246	  precedingQuotes: number;
247	  policies: Record<number, Policy>;
248	};
249	
250	const INITIAL_SCENARIO_STATE: ScenarioState = {
251	  results: [],
252	  precedingQuotes: 0,
253	  policies: {},
254	};
255	
256	// Every step reports exactly one result and leaves one policy at its index —
257	// the two things both step kinds always do. Recording them is named once here
258	// rather than rebuilt in each of them.
259	const withStepRecorded = (
260	  state: ScenarioState,
261	  result: Result,
262	  policyIndex: number,
263	  policy: Policy,
264	): ScenarioState => ({
265	  ...state,
266	  results: [...state.results, result],
267	  policies: { ...state.policies, [policyIndex]: policy },
268	});
269	
270	const afterQuote = (
271	  state: ScenarioState,
272	  items: Item[],
273	  customer: Customer,
274	  stepIndex: number,
275	): ScenarioState => ({
276	  ...withStepRecorded(
277	    state,
278	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
279	    stepIndex,
280	    policyFor(items),
281	  ),
282	  precedingQuotes: state.precedingQuotes + 1,
283	});
284	
285	const afterClaim = (
286	  state: ScenarioState,
287	  policyIndex: number,
288	  incident: Incident,
289	): ScenarioState => {
290	  const [result, settledPolicy] = claimFor(incident, state.policies[policyIndex]);
291	  return withStepRecorded(state, result, policyIndex, settledPolicy);
292	};
293	
294	const afterStep = (
295	  state: ScenarioState,
296	  step: Step,
297	  customer: Customer,
298	  stepIndex: number,
299	): ScenarioState =>
300	  step.op === "quote"
301	    ? afterQuote(state, step.items, customer, stepIndex)
302	    : afterClaim(state, step.policy, step.incident);
303	
304	export const runScenario = (scenario: Scenario): { results: Result[] } => {
305	  const { results } = scenario.steps.reduce(
306	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
307	    INITIAL_SCENARIO_STATE,
308	  );
309	  return { results };
310	};
